/* === Volta Studio — Shared Styles === */

/* --- Reset & Base --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  background-color: #F5F2ED;
  color: #1A1A1A;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

/* --- Typography --- */
h1, h2, h3, h4, .serif {
  font-family: 'Playfair Display', 'Times New Roman', serif;
  font-weight: 700;
  line-height: 1.15;
}

h1 {
  font-size: clamp(2.5rem, 6vw, 5rem);
  letter-spacing: -0.02em;
}

h2 {
  font-size: clamp(1.8rem, 4vw, 3.2rem);
}

h3 {
  font-size: clamp(1.3rem, 2.5vw, 1.8rem);
}

p {
  font-size: 1rem;
  color: #3A3A3A;
}

a {
  color: #1A1A1A;
  text-decoration: none;
  transition: opacity 0.3s ease;
}

a:hover {
  opacity: 0.6;
}

/* --- Header & Navigation --- */
.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 2rem 3rem;
  position: relative;
  z-index: 100;
}

.logo {
  font-family: 'Playfair Display', 'Times New Roman', serif;
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: #1A1A1A;
}

.nav-links {
  display: flex;
  list-style: none;
  gap: 2.5rem;
}

.nav-links a {
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: #1A1A1A;
}

.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 200;
  padding: 0;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: #1A1A1A;
  transition: all 0.3s ease;
  position: absolute;
}

.hamburger span:nth-child(1) { transform: translateY(-6px); }
.hamburger span:nth-child(2) { transform: translateY(0); }
.hamburger span:nth-child(3) { transform: translateY(6px); }

.hamburger.active span:nth-child(1) {
  transform: translateY(0) rotate(45deg);
}
.hamburger.active span:nth-child(2) {
  opacity: 0;
}
.hamburger.active span:nth-child(3) {
  transform: translateY(0) rotate(-45deg);
}

/* --- Mobile Menu Overlay --- */
.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  background: #F5F2ED;
  z-index: 150;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2rem;
}

.mobile-menu.active {
  display: flex;
}

.mobile-menu a {
  font-family: 'Playfair Display', 'Times New Roman', serif;
  font-size: 2.5rem;
  font-weight: 700;
  color: #1A1A1A;
  letter-spacing: -0.01em;
}

/* --- Shared Section Spacing --- */
section {
  padding: 6rem 3rem;
}

.section-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #8A857D;
  margin-bottom: 1.5rem;
}

/* --- Container --- */
.container {
  max-width: 1280px;
  margin: 0 auto;
}

.container-narrow {
  max-width: 720px;
  margin: 0 auto;
}

/* --- Hero --- */
.hero {
  padding: 4rem 3rem 6rem;
  min-height: 50vh;
  display: flex;
  align-items: center;
}

.hero h1 {
  max-width: 14ch;
}

/* --- Media Showcase --- */
.media-showcase {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  padding: 0 3rem 6rem;
  max-width: 1280px;
  margin: 0 auto;
}

.media-block {
  aspect-ratio: 4 / 3;
  border-radius: 4px;
}

.media-block:nth-child(1) { background-color: #C27A5E; }
.media-block:nth-child(2) { background-color: #8B9E7C; }
.media-block:nth-child(3) { background-color: #D4C5A9; }

/* --- Client Marquee --- */
.marquee-section {
  padding: 5rem 0;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  flex-wrap: nowrap;
  overflow: hidden;
  white-space: nowrap;
  padding: 1.2rem 0;
  border-top: 1px solid rgba(0,0,0,0.08);
}

.marquee-row:last-child {
  border-bottom: 1px solid rgba(0,0,0,0.08);
}

.marquee-track {
  display: flex;
  flex-shrink: 0;
  animation: marquee-left 40s linear infinite;
}

.marquee-row.reverse .marquee-track {
  animation: marquee-right 40s linear infinite;
}

.marquee-track span {
  font-family: 'Playfair Display', 'Times New Roman', serif;
  font-size: clamp(2rem, 4.5vw, 3.8rem);
  font-weight: 700;
  color: #1A1A1A;
  padding-right: 2rem;
  letter-spacing: -0.01em;
}

.marquee-track span::after {
  content: '◦';
  padding-left: 2rem;
  color: #C27A5E;
}

@keyframes marquee-left {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0%   { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* --- About Section --- */
.about {
  padding: 6rem 3rem;
}

.about-content {
  max-width: 720px;
}

.about-content p {
  font-size: 1.15rem;
  line-height: 1.75;
  margin-bottom: 1.5rem;
}

/* --- Philosophy Section --- */
.philosophy {
  padding: 6rem 3rem;
}

.philosophy-headline {
  font-family: 'Playfair Display', 'Times New Roman', serif;
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.15;
  margin-bottom: 2rem;
  letter-spacing: -0.01em;
}

.philosophy-headline em {
  font-style: italic;
}

.philosophy-body {
  max-width: 680px;
}

.philosophy-body p {
  font-size: 1.15rem;
  line-height: 1.75;
  margin-bottom: 1.5rem;
}

/* --- Service Details --- */
.service-details {
  padding: 6rem 3rem;
}

.service-question {
  font-size: clamp(1.5rem, 3.5vw, 2.5rem);
  font-family: 'Playfair Display', 'Times New Roman', serif;
  font-weight: 700;
  margin-bottom: 4rem;
  color: #1A1A1A;
  letter-spacing: -0.01em;
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem;
  max-width: 1280px;
  margin: 0 auto;
}

.service-card h3 {
  margin-bottom: 1.2rem;
}

.service-card p {
  font-size: 0.95rem;
  line-height: 1.7;
  color: #3A3A3A;
}

/* --- Founder Letter (Neweno) --- */
.neweno-letter {
  padding: 4rem 3rem 8rem;
}

.neweno-letter .section-label {
  margin-bottom: 3rem;
}

.letter-body {
  max-width: 620px;
  margin: 0 auto;
}

.letter-body h2 {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 2rem;
  letter-spacing: -0.01em;
}

.letter-body p {
  font-size: 1.1rem;
  line-height: 1.85;
  margin-bottom: 2rem;
  color: #2A2A2A;
}

.letter-signoff {
  margin-top: 3rem;
  font-family: 'Playfair Display', 'Times New Roman', serif;
  font-style: italic;
  font-size: 1.3rem;
}

/* --- Clients Grid --- */
.clients-section {
  padding: 4rem 3rem 8rem;
}

.clients-heading {
  margin-bottom: 4rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2rem;
  max-width: 1280px;
  margin: 0 auto;
}

.client-entry h3 {
  font-family: 'Playfair Display', 'Times New Roman', serif;
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  letter-spacing: -0.01em;
}

.client-entry p {
  font-size: 0.9rem;
  line-height: 1.6;
  color: #5A5A5A;
}

/* --- Contact Page --- */
.contact-hero {
  padding: 6rem 3rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 60vh;
}

.contact-heading {
  font-family: 'Playfair Display', 'Times New Roman', serif;
  font-size: clamp(4rem, 12vw, 10rem);
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: -0.03em;
  margin-bottom: 4rem;
  color: #1A1A1A;
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-width: 400px;
}

.contact-links a {
  font-family: 'Playfair Display', 'Times New Roman', serif;
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 600;
  color: #1A1A1A;
  letter-spacing: -0.01em;
  display: inline-block;
  width: fit-content;
}

/* --- Divider --- */
.divider {
  height: 1px;
  background: rgba(0,0,0,0.1);
  max-width: 1280px;
  margin: 0 3rem;
}

/* --- Footer --- */
.site-footer {
  padding: 3rem;
  text-align: center;
}

.site-footer p {
  font-size: 0.8rem;
  color: #8A857D;
  letter-spacing: 0.04em;
}

/* --- Responsive --- */
@media (max-width: 768px) {
  .site-header {
    padding: 1.5rem;
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
    position: relative;
    z-index: 200;
  }

  section,
  .hero,
  .about,
  .philosophy,
  .service-details,
  .clients-section,
  .neweno-letter,
  .contact-hero {
    padding: 3rem 1.5rem;
  }

  .media-showcase {
    grid-template-columns: 1fr;
    padding: 0 1.5rem 3rem;
    gap: 1rem;
  }

  .services-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .contact-heading {
    font-size: clamp(3rem, 14vw, 6rem);
  }

  .marquee-track span {
    font-size: 1.8rem;
  }

  .divider {
    margin: 0 1.5rem;
  }
}

@media (max-width: 480px) {
  .services-grid {
    grid-template-columns: 1fr;
  }

  .clients-grid {
    grid-template-columns: 1fr;
  }
}

